func (m workoutGroupMods) WithoutWorkoutGroupExercises() WorkoutGroupMod {
	return WorkoutGroupModFunc(func(ctx context.Context, o *WorkoutGroupTemplate) {
		o.r.WorkoutGroupExercises = nil
	})
}
